using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;
using NUnit.Framework;
using UnityEngine.TestTools;
using UnityEngine.SceneManagement;
namespace Wildfolk.Tests
{
    public sealed class RewardedAdsPlayTests
    {
        private string root,previous;private AccountService account;private Cloud cloud;private RewardedAds ads;private DevelopmentRewardedAdProvider provider;
        private sealed class Identity:IAccountIdentityProvider{public string PlayerId=>"ads-isolated-player";public bool Linked=>true;public Task Connect()=>Task.CompletedTask;public Task UseExisting()=>Task.CompletedTask;public void SignOut(bool clearSession=false){}}
        private sealed class Cloud:IAccountCloudTransport,IEconomyTransport,IRewardedTransport
        {
            public bool Verified,FailState;public string Day="2026-10-27",OperationId="11111111111111111111111111111111";public int Calls;public TaskCompletionSource<RewardedReply> Delay;
            Task<AccountReply> IAccountCloudTransport.Call(string op,Dictionary<string,object> input)=>Task.FromResult(new AccountReply{ok=true,profile=new CloudAccountProfile{Schema=1,PlayerId="ads-isolated-player",SupportId="LF-1234-5678-90AB-CDEF-1234",CreatedAt="2026-10-27T00:00:00Z",ProviderLinked=true,ClassProfile=CloudClassProfile.From(AccountProgression.New()),Entitlements=Array.Empty<AccountEntitlement>()}});
            Task<EconomyReply> IEconomyTransport.Call(string op,Dictionary<string,object> input)=>Task.FromResult(new EconomyReply{ok=true});
            public Task<RewardedReply> Call(string op,Dictionary<string,object> input){Calls++;if(FailState&&op=="GetRewardedState")return Task.FromResult(new RewardedReply{error="cloud_unavailable"});if(Delay!=null)return Delay.Task;var o=new AdOperation{OperationId=OperationId,Day=Day,Nonce=new string('a',64),State=Verified?"Granted":"Reserved",Amount=1};return Task.FromResult(new RewardedReply{ok=true,operation=op=="GetRewardedState"?null:o,state=op=="GetRewardedState"?new RewardedState{Schema=1,PlayerId="ads-isolated-player",EnvironmentId=BackendSettings.Current.Environment.Id,Remaining=Verified?0:1,Eligible=!Verified,GemPerRewardedAd=1,DailyRewardedGemLimit=1,ServerTime=Day+"T12:00:00Z",NextReset=DateTime.Parse(Day).AddDays(1).ToString("yyyy-MM-dd")+"T00:00:00Z"}:null});}
        }
        [UnitySetUp]public IEnumerator Setup(){previous=UnityEditor.SessionState.GetString("Wildfolk.QA.Directory","");root=Path.Combine(Path.GetTempPath(),"LowfireRewardedPlay-"+Guid.NewGuid().ToString("N"));UnityEditor.SessionState.SetString("Wildfolk.QA.Directory",root);ClassProfiles.DevelopmentProviders(new LocalAccountProgressionStore(Path.Combine(root,"guest")));cloud=new Cloud();account=AccountService.InstallDevelopment(new Identity(),cloud);EconomyService.InstallDevelopment(account,cloud);SceneFlow.Repository=SaveRepository.Default();yield return SceneManager.LoadSceneAsync(SceneFlow.HomeScene);yield return null;var connect=account.Connect();while(!connect.IsCompleted)yield return null;Assert.That(account.CloudAvailable,Is.True,"fixture connects from its own Home scene");provider=new DevelopmentRewardedAdProvider();ads=new RewardedAds(account,cloud,provider);}
        [TearDown]public void Cleanup(){ads.Dispose();EconomyService.ClearDevelopment();ClassProfiles.AttachCloud(null);SceneFlow.Repository=null;UnityEditor.SessionState.SetString("Wildfolk.QA.Directory",previous);if(Directory.Exists(root))Directory.Delete(root,true);}
        [UnityTest]public IEnumerator CancelAndNoFillConsumeNoRewardAndCanRetry(){foreach(var result in new[]{AdOutcome.Cancelled,AdOutcome.Unavailable,AdOutcome.Failed}){provider.Outcomes.Enqueue(result);var t=ads.WatchGem();while(!t.IsCompleted)yield return null;Assert.That(ads.Pending,Is.False);Assert.That(cloud.Verified,Is.False);}Assert.That(provider.Shows,Is.EqualTo(3));Assert.That(ads.LastError,Is.EqualTo("ad_failed"));}
        [UnityTest]public IEnumerator EarnedCallbackWaitsForServerAndParallelShowIsRejected(){provider.Outcomes.Enqueue(AdOutcome.Cancelled);cloud.Delay=new TaskCompletionSource<RewardedReply>();var t=ads.WatchGem();var other=ads.WatchGem();Assert.That(other.IsCompleted,Is.True);Assert.That(provider.Shows,Is.Zero);account.SignOut();cloud.Delay.SetResult(new RewardedReply{ok=true});while(!t.IsCompleted)yield return null;Assert.That(provider.Shows,Is.Zero);Assert.That(ads.State,Is.Null);}
        [UnityTest]public IEnumerator OnlyVerifiedServerStateReconcilesAndDisablesFurtherDailyShows(){provider.Outcomes.Enqueue(AdOutcome.Earned);cloud.Verified=true;var t=ads.WatchGem();while(!t.IsCompleted)yield return null;Assert.That(ads.Pending,Is.False);Assert.That(ads.State.Remaining,Is.Zero);Assert.That(ads.CanGem,Is.False);}
        [UnityTest]public IEnumerator EarnedReviveRetriesWithoutAnotherAdUntilWorldSaveSucceeds(){provider.Outcomes.Enqueue(AdOutcome.Cancelled);var success=true;ads.Show("run:1:ad",x=>success=x);yield return null;Assert.That(success,Is.False);provider.Outcomes.Enqueue(AdOutcome.Earned);ads.Show("run:1:ad",x=>success=x);yield return null;Assert.That(success,Is.True);ads.Resolve("run:1:ad",false);var shows=provider.Shows;provider.Available=false;ads.Show("run:1:ad",x=>success=x);Assert.That(success,Is.True);Assert.That(provider.Shows,Is.EqualTo(shows));Assert.That(ads.AvailableFor("new-run:1:ad"),Is.False);ads.Resolve("run:1:ad",true);Assert.That(ads.AvailableFor("run:1:ad"),Is.False);}

        [UnityTest]public IEnumerator FailedFreshEligibilityClearsPreviouslyEnabledAdButton(){var t=ads.Refresh();while(!t.IsCompleted)yield return null;Assert.That(ads.CanGem,Is.True);cloud.FailState=true;t=ads.Refresh();while(!t.IsCompleted)yield return null;Assert.That(ads.State,Is.Null);Assert.That(ads.CanGem,Is.False);}
        [UnityTest]public IEnumerator EarnedPreviousDayStaysDurableWhileANewDayCanBePrepared(){var scope=BackendSettings.Current.Environment.Id+":"+account.Profile.PlayerId;var journal=RewardedJournal.Open(scope);var old=new AdOperation{OperationId="22222222222222222222222222222222",Nonce=new string('b',64),Day="2026-10-27",Amount=1,State="Reserved"};journal.State.Pending=old;journal.State.Earned=true;journal.Save();cloud.Day="2026-10-28";var t=ads.Refresh();while(!t.IsCompleted)yield return null;Assert.That(ads.Pending,Is.True);Assert.That(ads.CanGem,Is.True);provider.Outcomes.Enqueue(AdOutcome.Cancelled);t=ads.WatchGem();while(!t.IsCompleted)yield return null;journal=RewardedJournal.Open(scope);Assert.That(journal.State.Waiting.Exists(x=>x.OperationId==old.OperationId),Is.True);Assert.That(journal.State.Pending.Day,Is.EqualTo("2026-10-28"));Assert.That(ads.Pending,Is.True);}
        private sealed class Loading:IRewardedAdProvider{public event Action Changed{add{}remove{}}public TaskCompletionSource<bool> Done=new TaskCompletionSource<bool>();public int Calls;public bool Supported=>true;public bool PrivacyOptionsRequired=>false;public bool Ready(AdPlacement p)=>Done.Task.IsCompleted;public Task Prepare(AdPlacement p){Calls++;return Done.Task;}public Task<AdOutcome> Show(AdRequestContext c,Action earned)=>Task.FromResult(AdOutcome.Unavailable);public void PrivacyOptions(){}public void Dispose(){Done.TrySetResult(false);}}
        [UnityTest]public IEnumerator ExplicitRetryDoesNotLaunchConcurrentReviveLoads(){ads.Dispose();var loading=new Loading();ads=new RewardedAds(account,cloud,loading);ads.Prepare("run:1:ad");ads.Prepare("run:1:ad",true);Assert.That(ads.Preparing,Is.True);Assert.That(ads.CanRetry,Is.False);Assert.That(loading.Calls,Is.EqualTo(1));loading.Done.SetResult(true);yield return null;Assert.That(ads.Preparing,Is.False);Assert.That(ads.AvailableFor("run:1:ad"),Is.True);}
    }
}
